#!/usr/bin/env bash
# @generated by @metaobjectsdev/pack-cloudflare (cloudflare-wrangler) — hand edits are kept by a three-way merge on regeneration; meta verify --codegen checks only the generated parts.
# Runs wrangler 4.168.0 (WRANGLER_VERSION overrides) for app.service acme::trips::Trips.web, as the narrow
# Cloudflare API token of one environment's deployment. The token and CLOUDFLARE_ACCOUNT_ID are read
# from the vault with keys-axi. The global-key variables (CLOUDFLARE_EMAIL, CLOUDFLARE_API_KEY) are unset
# so Wrangler cannot fall back to them, and so is any CLOUDFLARE_API_TOKEN the shell holds; the vault's token then becomes CLOUDFLARE_API_TOKEN.
#
# Needs: keys-axi (KEYS_AXI overrides where it is) and npx.
#
#   bash deploy/cloudflare/wrangler.sh <environment> <wrangler arguments>...
set -euo pipefail
cd "$(dirname "$0")/../.."

ENVIRONMENT="${1:-}"
[ "$#" -gt 0 ] && shift
WRANGLER_VERSION="${WRANGLER_VERSION:-4.168.0}"
KEYS_AXI="${KEYS_AXI:-$(command -v keys-axi || echo "$HOME/.local/bin/keys-axi")}"

case "$ENVIRONMENT" in
  production)
    VAULT_PROJECT=acme-deploy VAULT_ENV=dev TOKEN=ACME_WORKERS_TOKEN
    ;;
  *) echo 'usage: bash deploy/cloudflare/wrangler.sh <environment> <wrangler arguments>... (environments: production)' >&2; exit 2 ;;
esac

# shellcheck disable=SC2016 # the inner shell expands them: the token never enters this one
exec env -u CLOUDFLARE_EMAIL -u CLOUDFLARE_API_KEY -u CLOUDFLARE_API_TOKEN \
  "$KEYS_AXI" run --project "$VAULT_PROJECT" --env "$VAULT_ENV" --only "$TOKEN" CLOUDFLARE_ACCOUNT_ID -- \
  bash -c '
    set -euo pipefail
    [ -n "${!1:-}" ] || { echo "wrangler.sh: the deploy token $1 is empty or is not in the vault scope" >&2; exit 1; }
    export CLOUDFLARE_API_TOKEN="${!1}"
    [ "$1" = CLOUDFLARE_API_TOKEN ] || unset "$1"
    : "${CLOUDFLARE_ACCOUNT_ID:?CLOUDFLARE_ACCOUNT_ID is not in the vault scope}"
    version="$2"
    shift 2
    exec npx --yes "wrangler@$version" "$@"
  ' wrangler "$TOKEN" "$WRANGLER_VERSION" "$@"
